InvokeScript:
$Path = Resolve-Path -Path "$Env:ProgramFiles (x86)\Microsoft\Edge\Application\*\Installer\setup.exe" | Select-Object -Last 1

if (Test-Path $Path) {
    New-Item -Path "$Env:SystemRoot\SystemApps\Microsoft.MicrosoftEdge_8wekyb3d8bbwe\MicrosoftEdge.exe" -Force
    Start-Process -FilePath $Path -ArgumentList "--uninstall --system-level --force-uninstall --delete-profile" -Wait
    Write-Host "Microsoft Edge was removed"
} else {
    Write-Host "Microsoft Edge is not installed"
}

if (-not (Get-ComputerRestorePoint)) {
    Enable-ComputerRestore -Drive $Env:SystemDrive
}

Checkpoint-Computer -Description "System Restore Point created by WinUtil" -RestorePointType MODIFY_SETTINGS
Write-Host "System Restore Point Created Successfully" -ForegroundColor Green

$RazerPath = "$Env:SystemRoot\Installer\Razer"

if (Test-Path $RazerPath) {
  Remove-Item $RazerPath\* -Recurse -Force
} else {
  New-Item -Path $RazerPath -ItemType Directory
}

icacls $RazerPath /deny "Everyone:(W)"

Invoke-WinUtilExplorerUpdate
if ($sync.ThemeButton.Content -eq [char]0xF08C) {
  Invoke-WinutilThemeChange -theme "Auto"
}

# 设置 npm/pnpm/yarn 使用国内镜像 (npmmirror.com)
$npmrc = Join-Path $env:USERPROFILE '.npmrc'
$newKeys = @{
    'registry'            = 'https://registry.npmmirror.com'
    'electron_mirror'     = 'https://npmmirror.com/mirrors/electron/'
    'sass_binary_site'    = 'https://npmmirror.com/mirrors/node-sass/'
}
$lines = if (Test-Path $npmrc) { @(Get-Content -Path $npmrc) } else { @() }
$existing = @{}
foreach ($l in $lines) {
    if ($l -match '^\s*([^#=]+?)\s*=\s*(.+?)\s*$') { $existing[$matches[1]] = $matches[2] }
}
foreach ($k in $newKeys.Keys) { $existing[$k] = $newKeys[$k] }
$out = $existing.GetEnumerator() | Sort-Object Name | ForEach-Object { "$($_.Name)=$($_.Value)" }
[System.IO.File]::WriteAllLines($npmrc, $out)
Write-Host "[完成] npm/pnpm/yarn 镜像已切换为 npmmirror (registry / electron / node-sass)"

UndoScript:
# 撤销 npm 镜像设置，恢复官方源
$npmrc = Join-Path $env:USERPROFILE '.npmrc'
if (Test-Path $npmrc) {
    $lines = @(Get-Content -Path $npmrc) | Where-Object { $_ -notmatch '^\s*(registry|electron_mirror|sass_binary_site)\s*=' }
    [System.IO.File]::WriteAllLines($npmrc, $lines)
    Write-Host "[完成] npm 镜像设置已移除"
} else {
    Write-Host "[跳过] 未找到 .npmrc"
}

# 撤销 pip 镜像设置
$pipIni = Join-Path $env:APPDATA 'pip\pip.ini'
if (Test-Path $pipIni) {
    Remove-Item -Path $pipIni -Force
    Write-Host "[完成] pip 镜像设置已移除"
} else {
    Write-Host "[跳过] 未找到 pip.ini"
}

# 撤销 Maven 镜像配置
$settingsPath = Join-Path $env:USERPROFILE '.m2\settings.xml'
if (Test-Path $settingsPath) {
    Remove-Item -Path $settingsPath -Force
    Write-Host "[完成] Maven 镜像配置已移除"
} else {
    Write-Host "[跳过] 未找到 settings.xml"
}

InvokeScript:
# 设置 Git 全局配置（提交身份请自行设置 user.name / user.email）
$git = Get-Command git.exe -ErrorAction SilentlyContinue
if (-not $git) {
    foreach ($cand in @("$env:ProgramFiles\Git\cmd\git.exe", "$env:ProgramFiles\Git\bin\git.exe")) {
        if (Test-Path $cand) { $git = Get-Item $cand; break }
    }
}
if (-not $git) { Write-Host "[跳过] 未检测到 Git，请先在 Install 页安装 Git"; return }
git config --global core.autocrlf true
git config --global core.safecrlf warn
git config --global push.default simple
git config --global init.defaultBranch main
git config --global pull.rebase false
git config --global credential.helper manager
$name = git config --global user.name
$email = git config --global user.email
if (-not $name -and -not $email) {
    Write-Host "[提示] 请自行设置提交身份: git config --global user.name 你的名字"
    Write-Host "[提示] 以及: git config --global user.email you@example.com"
}
Write-Host "[完成] Git 全局配置已完成（换行符/推送/默认分支/凭据管理器）"

UndoScript:
# 撤销 Git 全局配置（仅移除本工具设置的键，不删除 user.name/user.email）
$git = Get-Command git.exe -ErrorAction SilentlyContinue
if (-not $git) {
    foreach ($cand in @("$env:ProgramFiles\Git\cmd\git.exe", "$env:ProgramFiles\Git\bin\git.exe")) {
        if (Test-Path $cand) { $git = Get-Item $cand; break }
    }
}
if (-not $git) { Write-Host "[跳过] 未检测到 Git"; return }
git config --global --unset-all core.autocrlf
git config --global --unset-all core.safecrlf
git config --global --unset-all push.default
git config --global --unset-all init.defaultBranch
git config --global --unset-all pull.rebase
git config --global --unset-all credential.helper
Write-Host "[完成] Git 全局配置（本工具设置的键）已移除"
